#!/usr/bin/env python3
"""Deterministic exhaustive solver for the two schedule scenarios."""
from __future__ import annotations
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
INPUT = HERE / "input.json"
RESULT = HERE / "result.json"
ORDER = ["A", "B", "C", "D", "E", "F"]


def overlaps(a0, a1, b0, b1):
    return a0 < b1 and b0 < a1


def load_input():
    with INPUT.open(encoding="utf-8") as f:
        return json.load(f)


def solve_scenario(data, scenario_name, scenario):
    jobs = data["jobs"]
    benches = data["benches"]
    pred = {j: [] for j in ORDER}
    for before, after in data["precedence"]:
        pred[after].append(before)
    unavailable = scenario["unavailable"]

    def allowed(bench, start, end):
        return all(not (u["bench"] == bench and overlaps(start, end, u["start"], u["end"]))
                   for u in unavailable)

    def enumerate_horizon(horizon):
        assigned = {}
        count = 0
        first = None

        def dfs(i):
            nonlocal count, first
            if i == len(ORDER):
                count += 1
                if first is None:
                    first = {j: dict(assigned[j]) for j in ORDER}
                return
            job = ORDER[i]
            earliest = data["constraints"].get("minimum_start", {}).get(job, 0)
            if pred[job]:
                earliest = max(earliest, max(assigned[p]["end"] for p in pred[job]))
            duration = jobs[job]
            for start in range(earliest, horizon - duration + 1):
                end = start + duration
                for bench in benches:
                    if not allowed(bench, start, end):
                        continue
                    if any(assigned[x]["bench"] == bench and
                           overlaps(start, end, assigned[x]["start"], assigned[x]["end"])
                           for x in assigned):
                        continue
                    if job in data["technician_jobs"] and any(
                        x in data["technician_jobs"] and
                        overlaps(start, end, assigned[x]["start"], assigned[x]["end"])
                        for x in assigned):
                        continue
                    assigned[job] = {"bench": bench, "start": start, "end": end}
                    dfs(i + 1)
                    del assigned[job]
        dfs(0)
        return count, first

    counts = {}
    for horizon in range(0, 64):
        count, first = enumerate_horizon(horizon)
        counts[str(horizon)] = count
        if count:
            schedule = first
            makespan = horizon
            break
    else:
        raise RuntimeError("search horizon exhausted")
    return {
        "scenario": scenario_name,
        "makespan": makespan,
        "schedule": {j: schedule[j] for j in ORDER},
        "proof": {
            "method": "exhaustive enumeration of every integer start and bench assignment within each horizon",
            "horizon_feasible_schedule_counts": counts,
            "shorter_horizons": [h for h in range(makespan) if counts[str(h)] == 0],
            "optimal_horizon_has_feasible_schedules": counts[str(makespan)] > 0,
        },
    }


def build_result(data):
    scenarios = {}
    for name in data["scenarios"]:
        scenarios[name] = solve_scenario(data, name, data["scenarios"][name])
    return {"format": 1, "input_digest_basis": "schedule/input.json", "scenarios": scenarios}


def main():
    try:
        data = load_input()
        result = build_result(data)
        serialized = json.dumps(result, indent=2, sort_keys=True) + "\n"
        if "--check" in sys.argv:
            if not RESULT.exists():
                print("CHECK FAIL: schedule/result.json is absent")
                return 1
            try:
                existing = RESULT.read_text(encoding="utf-8")
                parsed = json.loads(existing)
            except Exception as exc:
                print(f"CHECK FAIL: malformed schedule/result.json: {exc}")
                return 1
            if existing != serialized or parsed != result:
                print("CHECK FAIL: schedule/result.json is incorrect")
                return 1
            print("CHECK OK: schedule/result.json matches deterministic exhaustive solve")
            return 0
        RESULT.write_text(serialized, encoding="utf-8")
        print("WROTE schedule/result.json")
        return 0
    except Exception as exc:
        print(f"ERROR: {exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
import csv
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
INPUT = ROOT / "input.json"
RESULT = ROOT / "result.json"
CLEANED = ROOT / "cleaned.csv"
REPORT = ROOT / "report.md"

CALIBRATIONS = {
    "S1": lambda raw: (raw - 2) / 2,
    "S2": lambda raw: 3 * (raw + 1),
    "S3": lambda raw: 10 - raw,
}

def load_records():
    with INPUT.open(encoding="utf-8") as handle:
        records = json.load(handle)
    if not isinstance(records, list):
        raise ValueError("input must be a list")
    return records

def finite_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)

def build():
    records = load_records()
    groups = {}
    for index, record in enumerate(records):
        key = (record["sensor"], record["time"])
        groups.setdefault(key, []).append((index, record))

    cleaned = []
    conflicts = []
    invalid_records = []
    superseded_rows = []
    duplicates = []

    for key in sorted(groups):
        entries = groups[key]
        highest = max(record["revision"] for _, record in entries)
        superseded = [(index, record) for index, record in entries
                      if record["revision"] < highest]
        superseded_rows.extend(index for index, _ in superseded)
        current = [(index, record) for index, record in entries
                   if record["revision"] == highest]
        raw_values = [record["raw"] for _, record in current]
        if len(set(json.dumps(value, sort_keys=True) for value in raw_values)) > 1:
            conflicts.append({
                "sensor": key[0], "time": key[1], "revision": highest,
                "records": [index for index, _ in current],
            })
            continue
        if len(current) > 1:
            duplicates.extend(index for index, _ in current[1:])
        index, record = current[0]
        raw = record["raw"]
        if not finite_number(raw):
            invalid_records.append(index)
            continue
        calibrated = CALIBRATIONS[record["sensor"]](raw)
        cleaned.append({
            "sensor": record["sensor"], "time": record["time"],
            "revision": record["revision"], "raw": raw,
            "calibrated": calibrated,
            "in_band": 0 <= calibrated <= 10,
        })

    cleaned.sort(key=lambda row: (row["sensor"], row["time"]))
    by_sensor = {}
    for row in cleaned:
        sensor = row["sensor"]
        by_sensor.setdefault(sensor, []).append(row)
    aggregates = {}
    for sensor in sorted(by_sensor):
        values = [row["calibrated"] for row in by_sensor[sensor]]
        aggregates[sensor] = {
            "retained_count": len(values),
            "calibrated_min": min(values),
            "calibrated_max": max(values),
            "calibrated_mean": sum(values) / len(values),
            "in_band_count": sum(row["in_band"] for row in by_sensor[sensor]),
        }

    result = {
        "conflicts": conflicts,
        "invalid_records": invalid_records,
        "superseded_rows": superseded_rows,
        "duplicates": duplicates,
        "cleaned_rows": len(cleaned),
        "aggregates": aggregates,
    }
    return result, cleaned

def json_text(value):
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"

def csv_text(cleaned):
    columns = ["sensor", "time", "revision", "raw", "calibrated", "in_band"]
    import io
    output = io.StringIO(newline="")
    writer = csv.DictWriter(output, fieldnames=columns, lineterminator="\n")
    writer.writeheader()
    writer.writerows(cleaned)
    return output.getvalue()

def report_text(result):
    lines = [
        "# Quality processing report", "",
        "Records are grouped by sensor and time. Only the highest revision is considered; identical repeats collapse, while conflicting values quarantine the whole group.",
        "Nonnumeric surviving values are excluded. Calibrations are S1=(raw-2)/2, S2=3*(raw+1), and S3=10-raw; the inclusive in-band range is [0,10].", "",
        "## Exclusions and row history",
        "- Conflicting groups: " + ", ".join(f'{item[\"sensor\"]},{item[\"time\"]}@r{item[\"revision\"]}' for item in result["conflicts"]) + ".",
        "- Invalid records (input indices): " + ", ".join(map(str, result["invalid_records"])) + ".",
        "- Superseded rows (input indices): " + ", ".join(map(str, result["superseded_rows"])) + ".",
        "- Duplicate rows (input indices): " + ", ".join(map(str, result["duplicates"])) + ".", "",
        "## Aggregates",
        "| sensor | retained | calibrated min | calibrated max | calibrated mean | in-band |",
        "|---|---:|---:|---:|---:|---:|",
    ]
    for sensor, values in result["aggregates"].items():
        lines.append(f'| {sensor} | {values["retained_count"]} | {values["calibrated_min"]} | {values["calibrated_max"]} | {values["calibrated_mean"]} | {values["in_band_count"]} |')
    lines += ["", "The cleaned CSV is sorted by sensor and time; excluded groups do not enter these aggregates.", ""]
    return "\n".join(lines)

def expected():
    result, cleaned = build()
    return json_text(result), csv_text(cleaned), report_text(result)

def check():
    expected_result, expected_csv, expected_report = expected()
    actual = [(RESULT, expected_result), (CLEANED, expected_csv), (REPORT, expected_report)]
    for path, wanted in actual:
        if not path.is_file() or path.read_text(encoding="utf-8") != wanted:
            print(f"check failed: {path.name}")
            return 1
    print("quality check passed")
    return 0

def main():
    if "--check" in sys.argv[1:]:
        return check()
    result_text, cleaned_text, report = expected()
    RESULT.write_text(result_text, encoding="utf-8")
    CLEANED.write_text(cleaned_text, encoding="utf-8")
    REPORT.write_text(report, encoding="utf-8")
    print("quality reproduction wrote result.json, cleaned.csv, report.md")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())

