#!/usr/bin/env python3
"""Deterministic exhaustive shortest-closed-walk solver for routing/input.json."""
import itertools
import json
import os
import sys
from heapq import heappop, heappush

HERE = os.path.dirname(os.path.abspath(__file__))
INPUT = os.path.join(HERE, "input.json")
RESULT = os.path.join(HERE, "result.json")

def load_input():
    with open(INPUT, encoding="utf-8") as f:
        return json.load(f)

def graph(data, removed):
    g = {n: [] for n in data["nodes"]}
    banned = tuple(sorted(removed))
    for a, b, w in data["edges"]:
        e = tuple(sorted((a, b)))
        if e == banned:
            continue
        g[a].append((b, w))
        g[b].append((a, w))
    for n in g:
        g[n].sort(key=lambda x: (x[0], x[1]))
    return g

def shortest(g, source):
    dist = {n: 10**9 for n in g}
    path = {source: (source,)}
    dist[source] = 0
    heap = [(0, (source,), source)]
    while heap:
        d, p, u = heappop(heap)
        if (d, p) != (dist[u], path[u]):
            continue
        for v, w in g[u]:
            cand = (d + w, p + (v,))
            if cand < (dist[v], path[v]):
                dist[v], path[v] = cand
                heappush(heap, (cand[0], cand[1], v))
    return dist, path

def solve_scenario(data, removed):
    g = graph(data, removed)
    nodes = [data["start"]] + list(data["required"])
    tables = {}
    for source in nodes:
        d, p = shortest(g, source)
        tables[source] = {"distance": d, "path": {k: list(p[k]) for k in nodes}}
    rows = []
    for perm in itertools.permutations(data["required"]):
        order = [data["start"]] + list(perm) + [data["start"]]
        legs = []
        cost = 0
        physical = []
        for a, b in zip(order, order[1:]):
            leg = tables[a]["path"][b]
            legs.append({"from": a, "to": b, "cost": tables[a]["distance"][b], "path": leg})
            cost += tables[a]["distance"][b]
            physical.extend(leg if not physical else leg[1:])
        rows.append({"order": order, "cost": cost, "legs": legs, "walk": physical})
    rows.sort(key=lambda r: (r["cost"], r["order"], r["walk"]))
    best = rows[0]
    edge_walk = [{"from": a, "to": b, "cost": next(w for x,y,w in data["edges"] if {x,y} == {a,b})}
                 for a,b in zip(best["walk"], best["walk"][1:])]
    return {
        "removed_edge": list(removed) if removed else None,
        "permutation_count": len(rows),
        "shortest_path_tables": {
            s: {t: {"distance": tables[s]["distance"][t], "path": tables[s]["path"][t]}
                for t in nodes if t != s} for s in nodes
        },
        "order_costs": [{"order": r["order"], "cost": r["cost"]} for r in rows],
        "best_order": best["order"],
        "cost": best["cost"],
        "walk": best["walk"],
        "edge_walk": edge_walk
    }

def calculate(data):
    return {
        "format": 1,
        "input_digest_basis": "routing/input.json",
        "scenarios": [solve_scenario(data, ()), solve_scenario(data, ("R", "S"))]
    }

def canonical(obj):
    return json.dumps(obj, indent=2, sort_keys=True) + "\n"

def main(argv):
    if argv == ["--generate"]:
        with open(RESULT, "w", encoding="utf-8") as f:
            f.write(canonical(calculate(load_input())))
        print("generated routing/result.json")
        return 0
    if argv == ["--check"]:
        try:
            with open(RESULT, encoding="utf-8") as f:
                actual = json.load(f)
            expected = calculate(load_input())
            if actual != expected:
                print("check failed: result.json does not match deterministic calculation")
                return 1
            print("check passed: routing/result.json matches exhaustive calculation")
            return 0
        except (OSError, ValueError, KeyError, TypeError) as exc:
            print("check failed: " + str(exc))
            return 1
    print("usage: python3 solve.py --generate|--check")
    return 2

if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

