#!/usr/bin/env python3
"""Exhaustive, deterministic solver for packing/input.json."""
import argparse
import itertools
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parent
INPUT = ROOT / "input.json"
RESULT = ROOT / "result.json"


def load_input():
    with INPUT.open(encoding="utf-8") as f:
        return json.load(f)


def solve(data):
    boxes = list(data["boxes"])
    items = data["items"]
    ids = [item["id"] for item in items]
    capacities = {b: data["boxes"][b]["capacity"] for b in boxes}
    required = set(data["required"])
    forbidden_pairs = [tuple(pair) for pair in data["different_box_pairs"]]
    best_key = None
    best_assignment = None
    feasible = 0
    total = 0

    for choices in itertools.product((None, *boxes), repeat=len(items)):
        total += 1
        assignment = dict(zip(ids, choices))
        if any(assignment[i] is None for i in required):
            continue
        if any(assignment[a] is not None and assignment[a] == assignment[b]
               for a, b in forbidden_pairs):
            continue
        loads = {b: 0 for b in boxes}
        value = 0
        weight = 0
        for item in items:
            box = assignment[item["id"]]
            if box is not None:
                loads[box] += item["weight"]
                weight += item["weight"]
                value += item["value"]
        if any(loads[b] > capacities[b] for b in boxes):
            continue
        feasible += 1
        key = (-value, weight, tuple("" if assignment[i] is None else assignment[i] for i in ids))
        if best_key is None or key < best_key:
            best_key = key
            best_assignment = assignment

    selected = {i for i, b in best_assignment.items() if b is not None}
    item_by_id = {item["id"]: item for item in items}
    loads_out = {}
    total_value = 0
    total_weight = 0
    for box in boxes:
        box_ids = [i for i in ids if best_assignment[i] == box]
        box_weight = sum(item_by_id[i]["weight"] for i in box_ids)
        box_value = sum(item_by_id[i]["value"] for i in box_ids)
        loads_out[box] = {"capacity": capacities[box], "item_ids": box_ids,
                          "weight": box_weight, "value": box_value}
        total_value += box_value
        total_weight += box_weight
    return {
        "assignment": {i: best_assignment[i] for i in ids},
        "omitted_ids": [i for i in ids if i not in selected],
        "loads": loads_out,
        "objective": {"total_value": total_value, "total_selected_weight": total_weight},
        "exhaustive_proof": {
            "choice_space_assignments": total,
            "feasible_assignments": feasible,
            "optimization_order": ["maximize total_value", "minimize total_selected_weight"],
            "best_value": total_value,
            "minimum_weight_at_best_value": total_weight
        }
    }


def canonical(obj):
    return json.dumps(obj, indent=2, sort_keys=True) + "\n"


def expected():
    return solve(load_input())


def main():
    parser = argparse.ArgumentParser()
