#!/usr/bin/env python3
"""Deterministic exhaustive solver for the two schedule scenarios."""
from __future__ import annotations
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
INPUT = HERE / "input.json"
RESULT = HERE / "result.json"
ORDER = ["A", "B", "C", "D", "E", "F"]


def overlaps(a0, a1, b0, b1):
    return a0 < b1 and b0 < a1


def load_input():
    with INPUT.open(encoding="utf-8") as f:
        return json.load(f)


def solve_scenario(data, scenario_name, scenario):
    jobs = data["jobs"]
    benches = data["benches"]
    pred = {j: [] for j in ORDER}
    for before, after in data["precedence"]:
        pred[after].append(before)
    unavailable = scenario["unavailable"]

    def allowed(bench, start, end):
        return all(not (u["bench"] == bench and overlaps(start, end, u["start"], u["end"]))
                   for u in unavailable)

    def enumerate_horizon(horizon):
        assigned = {}
        count = 0
        first = None

        def dfs(i):
            nonlocal count, first
            if i == len(ORDER):
                count += 1
                if first is None:
                    first = {j: dict(assigned[j]) for j in ORDER}
                return
            job = ORDER[i]
            earliest = data["constraints"].get("minimum_start", {}).get(job, 0)
            if pred[job]:
                earliest = max(earliest, max(assigned[p]["end"] for p in pred[job]))
            duration = jobs[job]
            for start in range(earliest, horizon - duration + 1):
                end = start + duration
                for bench in benches:
                    if not allowed(bench, start, end):
                        continue
                    if any(assigned[x]["bench"] == bench and
                           overlaps(start, end, assigned[x]["start"], assigned[x]["end"])
                           for x in assigned):
                        continue
                    if job in data["technician_jobs"] and any(
                        x in data["technician_jobs"] and
                        overlaps(start, end, assigned[x]["start"], assigned[x]["end"])
                        for x in assigned):
                        continue
                    assigned[job] = {"bench": bench, "start": start, "end": end}
                    dfs(i + 1)
                    del assigned[job]
        dfs(0)
        return count, first

    counts = {}
    for horizon in range(0, 64):
        count, first = enumerate_horizon(horizon)
        counts[str(horizon)] = count
        if count:
            schedule = first
            makespan = horizon
            break
    else:
        raise RuntimeError("search horizon exhausted")
    return {
        "scenario": scenario_name,
        "makespan": makespan,
        "schedule": {j: schedule[j] for j in ORDER},
        "proof": {
            "method": "exhaustive enumeration of every integer start and bench assignment within each horizon",
            "horizon_feasible_schedule_counts": counts,
            "shorter_horizons": [h for h in range(makespan) if counts[str(h)] == 0],
            "optimal_horizon_has_feasible_schedules": counts[str(makespan)] > 0,
        },
    }


def build_result(data):
    scenarios = {}
    for name in data["scenarios"]:
        scenarios[name] = solve_scenario(data, name, data["scenarios"][name])
    return {"format": 1, "input_digest_basis": "schedule/input.json", "scenarios": scenarios}


def main():
    try:
        data = load_input()
        result = build_result(data)
        serialized = json.dumps(result, indent=2, sort_keys=True) + "\n"
        if "--check" in sys.argv:
            if not RESULT.exists():
                print("CHECK FAIL: schedule/result.json is absent")
                return 1
            try:
                existing = RESULT.read_text(encoding="utf-8")
                parsed = json.loads(existing)
            except Exception as exc:
                print(f"CHECK FAIL: malformed schedule/result.json: {exc}")
                return 1
            if existing != serialized or parsed != result:
                print("CHECK FAIL: schedule/result.json is incorrect")
                return 1
            print("CHECK OK: schedule/result.json matches deterministic exhaustive solve")
            return 0
        RESULT.write_text(serialized, encoding="utf-8")
        print("WROTE schedule/result.json")
        return 0
    except Exception as exc:
        print(f"ERROR: {exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

